import type { World } from './world.ts';

const q = (s: string): string => `'${s.replaceAll("'", "''")}'`;

/** Renders the world as seed SQL for `supabase db reset` (local only). */
export function toSeedSql(world: World): string {
  const out: string[] = [
    '-- GENERATED by `pnpm seed:generate` (packages/test-fixtures). Do not edit by hand.',
    '-- SYNTHETIC DEMO DATA ONLY — fictional kindergartens and people. Never load real data here.',
    '-- Loaded only by `supabase db reset` against the local stack; scripts/guard-local.mjs refuses linked/remote targets.',
    'begin;',
  ];
  for (const p of world.people) {
    out.push(
      `insert into auth.users (instance_id, id, aud, role, email, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current, phone_change, phone_change_token, reauthentication_token) values ('00000000-0000-0000-0000-000000000000', ${q(p.id)}, 'authenticated', 'authenticated', ${q(p.email)}, now(), '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', '', '', '', '', '');`,
      `insert into auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at) values (gen_random_uuid(), ${q(p.id)}, ${q(p.id)}, 'email', jsonb_build_object('sub', ${q(p.id)}, 'email', ${q(p.email)}, 'email_verified', true), now(), now(), null);`,
      `insert into public.profiles (id, first_name, last_name) values (${q(p.id)}, ${q(p.firstName)}, ${q(p.lastName)});`,
    );
    if (p.platformAdmin) out.push(`insert into private.platform_admins (profile_id) values (${q(p.id)});`);
  }
  for (const o of world.orgs) {
    out.push(`insert into public.organizations (id, name, slug) values (${q(o.id)}, ${q(o.name)}, ${q(o.slug)});`);
    for (const f of o.facilities) {
      out.push(`insert into public.facilities (id, organization_id, name, address) values (${q(f.id)}, ${q(o.id)}, ${q(f.name)}, ${q(f.address)});`);
    }
    const y = o.academicYear;
    out.push(`insert into public.academic_years (id, organization_id, name, starts_on, ends_on, status) values (${q(y.id)}, ${q(o.id)}, ${q(y.name)}, ${q(y.startsOn)}, ${q(y.endsOn)}, 'active');`);
    if (o.privacyNotice) {
      const n = o.privacyNotice;
      out.push(
        `insert into public.privacy_notices (organization_id, version, title, body, is_demo) values (${q(o.id)}, ${q(n.version)}, ${q(n.title)}, ${q(n.body)}, true);`,
        `update public.organizations set privacy_notice_version = ${q(n.version)} where id = ${q(o.id)};`,
      );
    }
    for (const g of o.groups) {
      out.push(`insert into public.groups (id, organization_id, facility_id, academic_year_id, name, capacity) values (${q(g.id)}, ${q(o.id)}, ${q(o.facilities[g.facilityIndex]!.id)}, ${q(y.id)}, ${q(g.name)}, ${g.capacity});`);
    }
  }
  const orgId = (key: string) => world.orgs.find((o) => o.key === key)!.id;
  for (const p of world.people) {
    for (const m of p.memberships) {
      out.push(`insert into public.memberships (id, organization_id, profile_id, role, valid_during) values (${q(m.id!)}, ${q(orgId(m.orgKey))}, ${q(p.id)}, '${m.role}', daterange('2026-09-01', null));`);
    }
  }
  for (const a of world.assignments) {
    const during = a.days ? `daterange(current_date + ${a.days.fromToday}, current_date + ${a.days.toToday})` : `daterange('2026-09-01', null)`;
    out.push(
      `insert into public.staff_assignments (id, organization_id, membership_id, group_id, assignment_type, valid_during, approved_by) values (${q(a.id)}, ${q(orgId(a.orgKey))}, ${q(a.membershipId)}, ${q(a.groupId)}, '${a.type}', ${during}, ${a.approvedBy ? q(a.approvedBy) : 'null'});`,
    );
  }
  for (const i of world.invitations) {
    const times = i.state === 'expired' ? `now() - interval '10 days', now() - interval '3 days'` : `now(), now() + interval '7 days'`;
    const revoked = i.state === 'revoked' ? `'revoked', ${q(i.createdBy)}, now()` : `'pending', null, null`;
    out.push(
      `insert into public.invitations (id, organization_id, email, role, first_name, last_name, created_by, created_at, expires_at, status, revoked_by, revoked_at) values (${q(i.id)}, ${q(orgId(i.orgKey))}, ${q(i.email)}, '${i.role}', ${q(i.firstName)}, ${q(i.lastName)}, ${q(i.createdBy)}, ${times}, ${revoked});`,
    );
  }
  for (const c of world.children) {
    out.push(`insert into public.children (id, organization_id, first_name, last_name, created_by) values (${q(c.id)}, ${q(orgId(c.orgKey))}, ${q(c.firstName)}, ${q(c.lastName)}, null);`);
    if (c.enrollmentId && c.groupId) {
      out.push(`insert into public.enrollments (id, organization_id, child_id, group_id, valid_during, created_by) values (${q(c.enrollmentId)}, ${q(orgId(c.orgKey))}, ${q(c.id)}, ${q(c.groupId)}, daterange('2026-09-01', null), null);`);
    }
  }
  for (const g of world.guardians) {
    out.push(`insert into public.guardians (id, organization_id, profile_id, first_name, last_name, created_by) values (${q(g.id)}, ${q(orgId(g.orgKey))}, ${g.profileId ? q(g.profileId) : 'null'}, ${q(g.firstName)}, ${q(g.lastName)}, null);`);
  }
  for (const l of world.guardianLinks) {
    out.push(
      `insert into public.child_guardians (id, organization_id, child_id, guardian_id, can_view, can_report_absence, receives_messages, valid_during, created_by) values (${q(l.id)}, ${q(orgId(l.orgKey))}, ${q(l.childId)}, ${q(l.guardianId)}, ${l.canView}, ${l.canReportAbsence}, ${l.receivesMessages}, daterange('2026-09-01', null), null);`,
    );
  }
  for (const a of world.pickupAuthorizations) {
    out.push(
      `insert into public.pickup_authorizations (id, organization_id, child_id, first_name, last_name, valid_during, created_by) values (${q(a.id)}, ${q(orgId(a.orgKey))}, ${q(a.childId)}, ${q(a.firstName)}, ${q(a.lastName)}, daterange('2026-09-01', null), null);`,
    );
  }
  out.push(...scenarioSql(world, orgId(world.scenario.orgKey)));
  out.push('commit;', '');
  return out.join('\n');
}

/**
 * D5 scenario SQL. Dates and times are relative to the kindergarten's "today" at load time (never in the future), and
 * audiences and notifications come from the real database functions (private.announcement_recipients, private.notify),
 * so the demo shows exactly what the product itself would have produced.
 */
function scenarioSql(world: World, org: string): string[] {
  const sc = world.scenario;
  const day = (daysAgo: number) => `(private.org_today(${q(org)}) - ${daysAgo})`;
  const at = (daysAgo: number, time: string) => `least(now() - interval '1 minute', (${day(daysAgo)} + time ${q(time)}) at time zone 'Europe/Zagreb')`;
  const out: string[] = ['-- D5 presentation scenario (relative to the load day)'];
  for (const a of sc.attendance) {
    out.push(
      `insert into public.attendance_records (id, organization_id, child_id, kind, occurred_at, local_date, recorded_by, source, handover_child_guardian_id, idempotency_key) values (${q(a.id)}, ${q(org)}, ${q(a.childId)}, 'check_in', ${at(0, a.time)}, ${day(0)}, ${q(sc.educatorId)}, 'app', ${a.handoverLinkId ? q(a.handoverLinkId) : 'null'}, ${q(a.idempotencyKey)});`,
    );
  }
  const ab = sc.absence;
  out.push(
    `insert into public.absence_records (id, organization_id, child_id, starts_on, ends_on, reported_by, source, created_at) values (${q(ab.id)}, ${q(org)}, ${q(ab.childId)}, ${day(-ab.fromToday)}, ${day(-ab.toToday)}, ${q(ab.reportedBy)}, 'guardian', ${at(0, '06:58')});`,
  );
  for (const a of sc.announcements) {
    const ids = a.audienceIds.length ? `array[${a.audienceIds.map((x) => `${q(x)}::uuid`).join(', ')}]` : `'{}'::uuid[]`;
    out.push(
      `insert into public.announcements (id, organization_id, author_id, title, body, audience_scope, audience_ids, audience_roles, status, published_at, created_at) values (${q(a.id)}, ${q(org)}, ${q(sc.managerId)}, ${q(a.title)}, ${q(a.body)}, '${a.scope}', ${ids}, array[${a.roles.map((x) => q(x)).join(', ')}], 'published', ${at(a.daysAgo, a.time)}, ${at(a.daysAgo, a.time)});`,
      `select private.notify(${q(org)}, array(select private.announcement_recipients(${q(a.id)})), 'announcement.published', 'announcement', ${q(a.id)});`,
    );
  }
  for (const d of sc.dailyEntries) {
    out.push(
      `insert into public.daily_entries (id, organization_id, group_id, entry_date, body, activity_tags, status, author_id, published_at) values (${q(d.id)}, ${q(org)}, ${q(sc.groupId)}, ${day(d.daysAgo)}, ${q(d.body)}, array[${d.tags.map((x) => q(x)).join(', ')}]::text[], 'published', ${q(sc.educatorId)}, ${at(d.daysAgo, '14:20')});`,
    );
  }
  const c = sc.conversation;
  // D-42: the conversation belongs to the child AND this guardian's record (c.guardianId is the guardian's account).
  out.push(
    `insert into public.conversations (id, organization_id, child_id, guardian_id) values (${q(c.id)}, ${q(org)}, ${q(c.childId)}, (select g.id from public.guardians g where g.organization_id = ${q(org)} and g.profile_id = ${q(c.guardianId)}));`,
  );
  for (const m of c.messages) {
    out.push(`insert into public.messages (id, organization_id, conversation_id, sender_id, body, created_at) values (${q(m.id)}, ${q(org)}, ${q(c.id)}, ${q(m.senderId)}, ${q(m.body)}, ${at(m.daysAgo, m.time)});`);
  }
  out.push(`select private.notify(${q(org)}, array[${q(c.guardianId)}::uuid], 'message.received', 'conversation', ${q(c.id)});`);
  return out;
}
